package br.com.sergio.gestaopedidos.service;
import br.com.sergio.gestaopedidos.dto.estoque.*;import br.com.sergio.gestaopedidos.entity.*;import br.com.sergio.gestaopedidos.enums.*;import br.com.sergio.gestaopedidos.exception.*;import br.com.sergio.gestaopedidos.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.core.context.SecurityContextHolder;import java.math.*;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor@Transactional public class EstoqueService{
 private final SaldoEstoqueRepository saldos;private final MovimentacaoEstoqueRepository movimentos;private final InsumoService insumos;private final ProdutoService produtos;private final ComposicaoProdutoRepository composicoes;
 public void processarCompra(Compra c){if(c.getStatus()==StatusCompra.ESTORNADA)return;for(ItemCompra i:c.getItens()){Ref r=ref(i);if((c.getTipoCompra()==TipoCompra.INSUMO)!=(r.tipo==TipoItemEstoque.INSUMO))throw new BusinessException("Item incompatível com o tipo da compra.");if(!movimentos.existsByItemCompraIdAndTipo(i.getId(),TipoMovimentacaoEstoque.ENTRADA_COMPRA))entrada(r,i.getQuantidade(),i.getValorTotalItem(),i.getCustoUnitario(),TipoMovimentacaoEstoque.ENTRADA_COMPRA,c.getDataCompra().atStartOfDay(),"Compra #"+c.getId(),i,null,i.getNomeHistorico(),i.getUnidadeHistorica());}}
 public void registrarEntradaManual(EntradaEstoqueRequest x){Ref r=ref(x.getTipoItem(),x.getReferenciaId(),true);BigDecimal q=qtd(x.getQuantidade(),r.unidade),v=positivo(x.getValorTotal());entrada(r,q,v,v.divide(q,6,RoundingMode.HALF_UP),TipoMovimentacaoEstoque.ENTRADA_AJUSTE,x.getDataMovimentacao(),texto(x.getObservacao()),null,null,r.nome,r.unidade);}
 public void registrarSaidaManual(SaidaEstoqueRequest x){if(!Set.of(TipoMovimentacaoEstoque.SAIDA_CONSUMO_MANUAL,TipoMovimentacaoEstoque.SAIDA_PERDA,TipoMovimentacaoEstoque.SAIDA_AJUSTE).contains(x.getTipo()))throw new BusinessException("Tipo de saída inválido.");Ref r=ref(x.getTipoItem(),x.getReferenciaId(),true);BigDecimal q=qtd(x.getQuantidade(),r.unidade);SaldoEstoque s=saldo(r);if(s.getQuantidadeAtual().compareTo(q)<0)throw new BusinessException("Estoque insuficiente. Disponível: "+s.getQuantidadeAtual().stripTrailingZeros().toPlainString()+" "+r.unidade.getSimbolo()+".");BigDecimal cu=s.getCustoMedioAtual(),v=q.multiply(cu).setScale(2,RoundingMode.HALF_UP);movimentos.save(mov(r,x.getDataMovimentacao(),x.getTipo(),q,v,cu,texto(x.getObservacao()),null,null,r.nome,r.unidade));s.setQuantidadeAtual(s.getQuantidadeAtual().subtract(q).setScale(3));s.setValorTotalEstoque(s.getValorTotalEstoque().subtract(v).max(BigDecimal.ZERO).setScale(2));if(s.getQuantidadeAtual().signum()==0){s.setCustoMedioAtual(zero6());s.setValorTotalEstoque(zero2());}saldos.save(s);}
 public void estornarCompra(Compra c){if(c.getStatus()==StatusCompra.ESTORNADA)throw new BusinessException("Esta compra já foi estornada.");List<MovimentacaoEstoque> os=movimentos.findByItemCompraCompraIdAndTipoOrderByIdAsc(c.getId(),TipoMovimentacaoEstoque.ENTRADA_COMPRA);if(os.isEmpty())throw new BusinessException("A compra ainda não possui entradas de estoque.");for(var o:os){Ref r=ref(o);SaldoEstoque s=saldo(r);if(s.getQuantidadeAtual().compareTo(o.getQuantidade())<0||s.getValorTotalEstoque().compareTo(o.getValorTotal())<0)throw new BusinessException("Não é possível estornar: o estoque atual não comporta a reversão desta compra.");movimentos.save(mov(r,LocalDateTime.now(),TipoMovimentacaoEstoque.ESTORNO_ENTRADA,o.getQuantidade(),o.getValorTotal(),o.getCustoUnitario(),"Estorno da compra #"+c.getId(),o.getItemCompra(),o,o.getNomeHistorico(),o.getUnidadeHistorica()));s.setQuantidadeAtual(s.getQuantidadeAtual().subtract(o.getQuantidade()).setScale(3));s.setValorTotalEstoque(s.getValorTotalEstoque().subtract(o.getValorTotal()).setScale(2));medio(s);saldos.save(s);}c.setStatus(StatusCompra.ESTORNADA);}
 public boolean compraMovimentada(Long id){return!movimentos.findByItemCompraCompraIdAndTipoOrderByIdAsc(id,TipoMovimentacaoEstoque.ENTRADA_COMPRA).isEmpty();}
 public BigDecimal processarProducao(Producao producao,Map<Long,Map<Insumo,BigDecimal>> consumosPorProduto,BigDecimal gastosAdicionais){
  if(consumosPorProduto==null||consumosPorProduto.isEmpty())throw new BusinessException("A produção deve possuir consumo de Insumos.");
  Map<Insumo,BigDecimal> consumos=new LinkedHashMap<>();
  for(ItemProducao item:producao.getItens()){
   BigDecimal quantidadeProduzida=qtd(item.getQuantidade(),item.getUnidadeHistorica());
   Map<Insumo,BigDecimal> itens=consumosPorProduto.get(item.getProduto().getId());
   if(quantidadeProduzida.signum()<=0)throw new BusinessException("A quantidade produzida deve ser maior que zero.");
   if(itens==null||itens.isEmpty())throw new BusinessException("O produto "+item.getNomeHistorico()+" não possui consumo definido na Ficha Técnica.");
   itens.forEach((insumo,quantidade)->consumos.merge(insumo,qtd(quantidade,insumo.getUnidadeMedida()),BigDecimal::add));
  }
  List<Map.Entry<Insumo,BigDecimal>> entradas=consumos.entrySet().stream().sorted(Map.Entry.comparingByKey(Comparator.comparing(Insumo::getId))).toList();
  Map<Long,SaldoEstoque> saldosInsumos=new LinkedHashMap<>();List<String> faltas=new ArrayList<>();
  for(var entrada:entradas){Insumo insumo=entrada.getKey();Ref ref=refInsumo(insumo);BigDecimal quantidade=qtd(entrada.getValue(),ref.unidade);SaldoEstoque saldo=saldo(ref);saldosInsumos.put(insumo.getId(),saldo);if(saldo.getCustoMedioAtual().signum()<0)throw new BusinessException("O custo médio do insumo "+insumo.getNome()+" não pode ser negativo.");if(saldo.getQuantidadeAtual().compareTo(quantidade)<0){BigDecimal falta=quantidade.subtract(saldo.getQuantidadeAtual()).setScale(3);faltas.add(insumo.getNome()+": necessário "+formatarQuantidade(quantidade,ref.unidade)+", disponível "+formatarQuantidade(saldo.getQuantidadeAtual(),ref.unidade)+", faltando "+formatarQuantidade(falta,ref.unidade));}}
  if(!faltas.isEmpty())throw new BusinessException("Estoque insuficiente para confirmar a produção: "+String.join("; ",faltas)+".");

  Map<Long,BigDecimal> custosLotes=new LinkedHashMap<>();
  for(ItemProducao item:producao.getItens().stream().sorted(Comparator.comparing(i->i.getProduto().getId())).toList()){
   BigDecimal custo=consumosPorProduto.get(item.getProduto().getId()).entrySet().stream().map(e->e.getValue().multiply(saldosInsumos.get(e.getKey().getId()).getCustoMedioAtual())).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);
   if(custo.signum()<0)throw new BusinessException("O custo do lote não pode ser negativo.");
   custosLotes.put(item.getProduto().getId(),custo);
  }
  BigDecimal totalSaidas=entradas.stream().map(e->qtd(e.getValue(),e.getKey().getUnidadeMedida()).multiply(saldosInsumos.get(e.getKey().getId()).getCustoMedioAtual()).setScale(2,RoundingMode.HALF_UP)).reduce(zero2(),BigDecimal::add);
  BigDecimal totalLotes=custosLotes.values().stream().reduce(zero2(),BigDecimal::add);
  Long ultimo=custosLotes.keySet().stream().reduce((a,b)->b).orElseThrow();
  custosLotes.put(ultimo,custosLotes.get(ultimo).add(totalSaidas.subtract(totalLotes)).setScale(2,RoundingMode.HALF_UP));
  custosLotes.put(ultimo,custosLotes.get(ultimo).add(dinheiro(gastosAdicionais)).setScale(2,RoundingMode.HALF_UP));

  String usuario=Optional.ofNullable(SecurityContextHolder.getContext().getAuthentication()).map(a->a.getName()).orElse("sistema");LocalDateTime agora=LocalDateTime.now();
  for(var entrada:entradas){Insumo insumo=entrada.getKey();Ref ref=refInsumo(insumo);BigDecimal quantidade=qtd(entrada.getValue(),ref.unidade);SaldoEstoque saldo=saldosInsumos.get(insumo.getId());BigDecimal antes=saldo.getQuantidadeAtual(),depois=antes.subtract(quantidade).setScale(3),custoUnitario=saldo.getCustoMedioAtual(),valor=quantidade.multiply(custoUnitario).setScale(2,RoundingMode.HALF_UP);movimentos.save(movProducao(ref,producao,agora,TipoMovimentacaoEstoque.SAIDA_CONSUMO_PRODUCAO,quantidade,valor,custoUnitario,antes,depois,usuario));saldo.setQuantidadeAtual(depois);saldo.setValorTotalEstoque(saldo.getValorTotalEstoque().subtract(valor).max(BigDecimal.ZERO).setScale(2));if(depois.signum()==0){saldo.setCustoMedioAtual(zero6());saldo.setValorTotalEstoque(zero2());}saldos.save(saldo);}
  for(ItemProducao item:producao.getItens().stream().sorted(Comparator.comparing(i->i.getProduto().getId())).toList()){Produto produto=item.getProduto();Ref ref=new Ref(TipoItemEstoque.PREPARACAO_PRODUZIDA,produto.getId(),null,produto,item.getNomeHistorico(),item.getUnidadeHistorica(),produto.getAtivo(),produto.getEstoqueMinimo());BigDecimal quantidade=qtd(item.getQuantidade(),ref.unidade),valor=custosLotes.get(produto.getId()),custoUnitario=valor.divide(quantidade,6,RoundingMode.HALF_UP);if(custoUnitario.signum()<0)throw new BusinessException("O custo unitário da produção não pode ser negativo.");item.setCustoTotal(valor);item.setCustoUnitario(custoUnitario);SaldoEstoque saldo=saldo(ref);BigDecimal antes=saldo.getQuantidadeAtual(),depois=antes.add(quantidade).setScale(3),novoValor=saldo.getValorTotalEstoque().add(valor).setScale(2),novoCusto=novoValor.divide(depois,6,RoundingMode.HALF_UP);movimentos.save(movProducao(ref,producao,agora,TipoMovimentacaoEstoque.ENTRADA_PRODUCAO,quantidade,valor,custoUnitario,antes,depois,usuario));saldo.setQuantidadeAtual(depois);saldo.setValorTotalEstoque(novoValor);saldo.setCustoMedioAtual(novoCusto);saldos.save(saldo);}
  return totalSaidas.setScale(2,RoundingMode.HALF_UP);
 }
 public BigDecimal processarProducao(Producao producao,Map<Long,Map<Insumo,BigDecimal>> consumosPorProduto){return processarProducao(producao,consumosPorProduto,BigDecimal.ZERO);}
 public void processarPedido(Pedido pedido){
  if(Boolean.TRUE.equals(pedido.getEstoqueMovimentado()))return;
  Map<Chave,Necessidade> necessidades=new LinkedHashMap<>();
  for(ItemPedido item:pedido.getItens()){
   Produto produto=item.getProduto();BigDecimal quantidade=qtd(item.getQuantidade(),unidade(produto));
   if(produto.getTipoProduto()==TipoProduto.PRODUTO_REVENDA){adicionar(necessidades,refProduto(produto,TipoItemEstoque.PRODUTO_REVENDA),quantidade);continue;}
   if(produto.getTipoProduto()!=TipoProduto.PRODUTO_COMERCIAL)throw new BusinessException("O produto "+produto.getNome()+" não pode ser movimentado em Pedido.");
   ComposicaoProduto composicao=composicoes.findDetailedByProdutoComercialId(produto.getId()).filter(c->Boolean.TRUE.equals(c.getAtiva())).orElseThrow(()->new BusinessException("O produto "+produto.getNome()+" não possui Composição Comercial ativa."));
   if(composicao.getItens().isEmpty())throw new BusinessException("O produto "+produto.getNome()+" possui Composição Comercial vazia.");
   for(ItemComposicaoProduto componente:composicao.getItens()){
    Ref ref=componente.getInsumo()!=null?refInsumo(componente.getInsumo()):refProduto(componente.getPreparacao(),TipoItemEstoque.PREPARACAO_PRODUZIDA);
    adicionar(necessidades,ref,quantidade.multiply(componente.getQuantidade()).setScale(3,RoundingMode.HALF_UP));
   }
  }
  List<Necessidade> ordenadas=necessidades.values().stream().sorted(Comparator.comparing((Necessidade n)->n.ref.tipo.name()).thenComparing(n->n.ref.id)).toList();
  List<String> faltas=new ArrayList<>();Map<Chave,SaldoEstoque> bloqueados=new LinkedHashMap<>();
  for(Necessidade n:ordenadas){SaldoEstoque saldo=saldo(n.ref);bloqueados.put(new Chave(n.ref.tipo,n.ref.id),saldo);if(saldo.getQuantidadeAtual().compareTo(n.quantidade)<0)faltas.add(n.ref.nome+": necessário "+formatarQuantidade(n.quantidade,n.ref.unidade)+", disponível "+formatarQuantidade(saldo.getQuantidadeAtual(),n.ref.unidade));}
  if(!faltas.isEmpty())throw new BusinessException("Estoque insuficiente para confirmar o pedido: "+String.join("; ",faltas)+".");
  String usuario=Optional.ofNullable(SecurityContextHolder.getContext().getAuthentication()).map(a->a.getName()).orElse("sistema");LocalDateTime agora=LocalDateTime.now();
  for(Necessidade n:ordenadas){SaldoEstoque saldo=bloqueados.get(new Chave(n.ref.tipo,n.ref.id));BigDecimal antes=saldo.getQuantidadeAtual(),depois=antes.subtract(n.quantidade).setScale(3),cu=saldo.getCustoMedioAtual(),valor=n.quantidade.multiply(cu).setScale(2,RoundingMode.HALF_UP);movimentos.save(MovimentacaoEstoque.builder().tipoItem(n.ref.tipo).insumo(n.ref.insumo).produto(n.ref.produto).nomeHistorico(n.ref.nome).dataMovimentacao(agora).tipo(TipoMovimentacaoEstoque.SAIDA_VENDA).quantidade(n.quantidade).unidadeHistorica(n.ref.unidade).valorTotal(valor).custoUnitario(cu).saldoAnterior(antes).saldoPosterior(depois).usuarioResponsavel(usuario).observacao("Pedido #"+pedido.getId()).pedido(pedido).build());saldo.setQuantidadeAtual(depois);saldo.setValorTotalEstoque(saldo.getValorTotalEstoque().subtract(valor).max(BigDecimal.ZERO).setScale(2));if(depois.signum()==0){saldo.setCustoMedioAtual(zero6());saldo.setValorTotalEstoque(zero2());}saldos.save(saldo);}
  pedido.setEstoqueMovimentado(true);pedido.setEstoqueMovimentadoEm(agora);
 }
 public void estornarPedido(Pedido pedido){
  if(!Boolean.TRUE.equals(pedido.getEstoqueMovimentado()))return;
  List<MovimentacaoEstoque> todas=movimentos.findByPedidoIdOrderByIdAsc(pedido.getId());Set<Long> estornadas=todas.stream().filter(m->m.getTipo()==TipoMovimentacaoEstoque.ESTORNO_SAIDA&&m.getMovimentacaoOrigem()!=null).map(m->m.getMovimentacaoOrigem().getId()).collect(java.util.stream.Collectors.toSet());
  List<MovimentacaoEstoque> origens=todas.stream().filter(m->m.getTipo()==TipoMovimentacaoEstoque.SAIDA_VENDA&&!estornadas.contains(m.getId())).sorted(Comparator.comparing(m->m.getTipoItem().name()+":"+(m.getInsumo()!=null?m.getInsumo().getId():m.getProduto().getId()))).toList();
  String usuario=Optional.ofNullable(SecurityContextHolder.getContext().getAuthentication()).map(a->a.getName()).orElse("sistema");LocalDateTime agora=LocalDateTime.now();
  for(MovimentacaoEstoque origem:origens){Ref ref=ref(origem);SaldoEstoque saldo=saldo(ref);BigDecimal antes=saldo.getQuantidadeAtual(),depois=antes.add(origem.getQuantidade()).setScale(3),novoValor=saldo.getValorTotalEstoque().add(origem.getValorTotal()).setScale(2);movimentos.save(MovimentacaoEstoque.builder().tipoItem(ref.tipo).insumo(ref.insumo).produto(ref.produto).nomeHistorico(origem.getNomeHistorico()).dataMovimentacao(agora).tipo(TipoMovimentacaoEstoque.ESTORNO_SAIDA).quantidade(origem.getQuantidade()).unidadeHistorica(origem.getUnidadeHistorica()).valorTotal(origem.getValorTotal()).custoUnitario(origem.getCustoUnitario()).saldoAnterior(antes).saldoPosterior(depois).usuarioResponsavel(usuario).observacao("Estorno do pedido #"+pedido.getId()).pedido(pedido).movimentacaoOrigem(origem).build());saldo.setQuantidadeAtual(depois);saldo.setValorTotalEstoque(novoValor);saldo.setCustoMedioAtual(novoValor.divide(depois,6,RoundingMode.HALF_UP));saldos.save(saldo);}
  pedido.setEstoqueMovimentado(false);pedido.setEstoqueMovimentadoEm(null);
 }
 @Transactional(readOnly=true)public List<MovimentacaoPedidoResponse> movimentacoesPedido(Long pedidoId){return movimentos.findByPedidoIdOrderByIdAsc(pedidoId).stream().map(m->MovimentacaoPedidoResponse.builder().id(m.getId()).produtoNome(m.getNomeHistorico()).tipo(m.getTipo()).quantidade(m.getQuantidade()).unidade(m.getUnidadeHistorica()).saldoAnterior(m.getSaldoAnterior()).saldoPosterior(m.getSaldoPosterior()).dataMovimentacao(m.getDataMovimentacao()).build()).toList();}
 @Transactional(readOnly=true)public Page<SaldoEstoqueResponse> listar(String nome,TipoItemEstoque cat,String situacao,Boolean ativo,Pageable p){return saldos.listar(limpar(nome),cat==null?"":cat.name(),limpar(situacao),ativo,p).map(this::map);}
 @Transactional(readOnly=true)public EstoqueIndicadoresResponse indicadores(){BigDecimal a=dinheiro(saldos.somarValor(TipoItemEstoque.INSUMO)),b=dinheiro(saldos.somarValor(TipoItemEstoque.PRODUTO_REVENDA)),c=dinheiro(saldos.somarValor(TipoItemEstoque.PREPARACAO_PRODUZIDA));return EstoqueIndicadoresResponse.builder().itensComSaldo(saldos.contarComSaldo()).abaixoDoMinimo(saldos.listar("","","BAIXO",null,PageRequest.of(0,1)).getTotalElements()).valorInsumos(a).valorRevenda(b).valorProduzidos(c).valorTotal(a.add(b).add(c)).build();}
 @Transactional(readOnly=true)public Page<MovimentacaoEstoqueResponse> movimentacoes(LocalDate ini,LocalDate fim,TipoItemEstoque cat,Long ref,TipoMovimentacaoEstoque tipo,Long compra,Pageable p){return movimentos.listar(ini==null?null:ini.atStartOfDay(),fim==null?null:fim.plusDays(1).atStartOfDay().minusNanos(1),cat,ref,tipo,compra,p).map(this::map);}
 @Transactional(readOnly=true)public DetalhesEstoqueResponse detalhes(TipoItemEstoque tipo,Long id){Ref r=ref(tipo,id,false);SaldoEstoque s=saldos.buscarSaldo(tipo,id).orElse(novo(r));return DetalhesEstoqueResponse.builder().estoque(montar(r,s.getQuantidadeAtual(),s.getCustoMedioAtual(),s.getValorTotalEstoque(),s.getAtualizadoEm())).movimentacoes(movimentos.ultimas(tipo,id,PageRequest.of(0,20)).stream().map(this::map).toList()).build();}
 private void entrada(Ref r,BigDecimal q,BigDecimal v,BigDecimal cu,TipoMovimentacaoEstoque tipo,LocalDateTime data,String obs,ItemCompra item,MovimentacaoEstoque origem,String nome,UnidadeMedida un){q=qtd(q,un);v=dinheiro(v);SaldoEstoque s=saldo(r);BigDecimal nq=s.getQuantidadeAtual().add(q).setScale(3),nv=s.getValorTotalEstoque().add(v).setScale(2);s.setQuantidadeAtual(nq);s.setValorTotalEstoque(nv);s.setCustoMedioAtual(nv.divide(nq,6,RoundingMode.HALF_UP));movimentos.save(mov(r,data,tipo,q,v,cu,obs,item,origem,nome,un));saldos.save(s);}
 private SaldoEstoque saldo(Ref r){if(r.tipo==TipoItemEstoque.INSUMO)saldos.bloquearInsumo(r.id).orElseThrow(()->new ResourceNotFoundException("Insumo não encontrado."));else saldos.bloquearProduto(r.id).orElseThrow(()->new ResourceNotFoundException("Produto não encontrado."));return saldos.bloquearSaldo(r.tipo,r.id).orElseGet(()->novo(r));}private SaldoEstoque novo(Ref r){return SaldoEstoque.builder().tipoItem(r.tipo).insumo(r.insumo).produto(r.produto).build();}
 private Ref ref(TipoItemEstoque t,Long id,boolean ativo){if(t==null||id==null)throw new BusinessException("Selecione o tipo e o item.");if(t==TipoItemEstoque.INSUMO){Insumo i=insumos.buscarEntidade(id);if(ativo&&!Boolean.TRUE.equals(i.getAtivo()))throw new BusinessException("Este insumo não está disponível para novas movimentações.");return new Ref(t,id,i,null,i.getNome(),i.getUnidadeMedida(),i.getAtivo(),i.getEstoqueMinimo());}Produto p=produtos.buscarEntidadePorId(id);TipoProduto esperado=t==TipoItemEstoque.PREPARACAO_PRODUZIDA?TipoProduto.PREPARACAO_PRODUZIDA:TipoProduto.PRODUTO_REVENDA;if(p.getTipoProduto()!=esperado)throw new BusinessException(t==TipoItemEstoque.PREPARACAO_PRODUZIDA?"Somente preparações produzidas podem receber este ajuste.":"Somente produtos de revenda podem possuir estoque.");if(ativo&&!Boolean.TRUE.equals(p.getAtivo()))throw new BusinessException("Este produto não está disponível para novas movimentações.");return new Ref(t,id,null,p,p.getNome(),p.getUnidadeVenda()==UnidadeVenda.UNIDADE?UnidadeMedida.UNIDADE:UnidadeMedida.QUILOGRAMA,p.getAtivo(),p.getEstoqueMinimo());}
 private Ref refInsumo(Insumo i){return new Ref(TipoItemEstoque.INSUMO,i.getId(),i,null,i.getNome(),i.getUnidadeMedida(),i.getAtivo(),i.getEstoqueMinimo());}
 private Ref refProduto(Produto p,TipoItemEstoque tipo){TipoProduto esperado=tipo==TipoItemEstoque.PREPARACAO_PRODUZIDA?TipoProduto.PREPARACAO_PRODUZIDA:TipoProduto.PRODUTO_REVENDA;if(p==null||p.getTipoProduto()!=esperado)throw new BusinessException("Componente de estoque inválido.");return new Ref(tipo,p.getId(),null,p,p.getNome(),unidade(p),p.getAtivo(),p.getEstoqueMinimo());}
 private UnidadeMedida unidade(Produto p){return p.getUnidadeVenda()==UnidadeVenda.UNIDADE?UnidadeMedida.UNIDADE:UnidadeMedida.QUILOGRAMA;}
 private void adicionar(Map<Chave,Necessidade> necessidades,Ref ref,BigDecimal quantidade){quantidade=qtd(quantidade,ref.unidade);Chave chave=new Chave(ref.tipo,ref.id);Necessidade atual=necessidades.get(chave);necessidades.put(chave,new Necessidade(ref,atual==null?quantidade:atual.quantidade.add(quantidade).setScale(3)));}
 private Ref ref(ItemCompra i){if(i.getInsumo()!=null&&i.getProduto()==null)return new Ref(TipoItemEstoque.INSUMO,i.getInsumo().getId(),i.getInsumo(),null,i.getNomeHistorico(),i.getUnidadeHistorica(),i.getInsumo().getAtivo(),i.getInsumo().getEstoqueMinimo());if(i.getProduto()!=null&&i.getInsumo()==null&&i.getProduto().getTipoProduto()==TipoProduto.PRODUTO_REVENDA)return new Ref(TipoItemEstoque.PRODUTO_REVENDA,i.getProduto().getId(),null,i.getProduto(),i.getNomeHistorico(),i.getUnidadeHistorica(),i.getProduto().getAtivo(),i.getProduto().getEstoqueMinimo());throw new BusinessException("Referência de estoque inválida.");}private Ref ref(MovimentacaoEstoque m){return new Ref(m.getTipoItem(),m.getInsumo()!=null?m.getInsumo().getId():m.getProduto().getId(),m.getInsumo(),m.getProduto(),m.getNomeHistorico(),m.getUnidadeHistorica(),true,BigDecimal.ZERO);}
 private MovimentacaoEstoque mov(Ref r,LocalDateTime d,TipoMovimentacaoEstoque t,BigDecimal q,BigDecimal v,BigDecimal c,String obs,ItemCompra item,MovimentacaoEstoque origem,String nome,UnidadeMedida un){return MovimentacaoEstoque.builder().tipoItem(r.tipo).insumo(r.insumo).produto(r.produto).nomeHistorico(nome).dataMovimentacao(d==null?LocalDateTime.now():d).tipo(t).quantidade(q).unidadeHistorica(un).valorTotal(v).custoUnitario(c.setScale(6,RoundingMode.HALF_UP)).observacao(obs).itemCompra(item).movimentacaoOrigem(origem).build();}
 private MovimentacaoEstoque movProducao(Ref r,Producao p,LocalDateTime d,TipoMovimentacaoEstoque t,BigDecimal q,BigDecimal v,BigDecimal c,BigDecimal antes,BigDecimal depois,String usuario){return MovimentacaoEstoque.builder().tipoItem(r.tipo).insumo(r.insumo).produto(r.produto).nomeHistorico(r.nome).dataMovimentacao(d).tipo(t).quantidade(q).unidadeHistorica(r.unidade).valorTotal(v).custoUnitario(c.setScale(6,RoundingMode.HALF_UP)).saldoAnterior(antes).saldoPosterior(depois).usuarioResponsavel(usuario).observacao("Produção #"+p.getId()).producao(p).build();}
 private SaldoEstoqueResponse map(SaldoEstoqueRepository.Visao v){Ref r=new Ref(TipoItemEstoque.valueOf(v.getTipoItem()),v.getReferenciaId(),null,null,v.getItemNome(),UnidadeMedida.valueOf(v.getUnidade()),v.getAtivo(),v.getEstoqueMinimo());return montar(r,v.getQuantidadeAtual(),v.getCustoMedioAtual(),v.getValorTotalEstoque(),v.getAtualizadoEm());}private SaldoEstoqueResponse montar(Ref r,BigDecimal q,BigDecimal c,BigDecimal v,LocalDateTime u){q=q==null?BigDecimal.ZERO:q;BigDecimal min=r.minimo==null?BigDecimal.ZERO:r.minimo;boolean baixo=min.signum()>0&&q.compareTo(min)<=0;String sit=q.signum()==0?"Sem estoque":baixo?"Estoque baixo":min.signum()==0?"Sem mínimo configurado":"Normal";return SaldoEstoqueResponse.builder().tipoItem(r.tipo).referenciaId(r.id).nome(r.nome).unidade(r.unidade).ativo(r.ativo).estoqueAtual(q).estoqueMinimo(min).abaixoDoMinimo(baixo).situacao(sit).custoMedioAtual(c==null?zero6():c).valorEstimadoEstoque(v==null?zero2():v).ultimaMovimentacao(u).build();}
 private MovimentacaoEstoqueResponse map(MovimentacaoEstoque m){Long id=m.getInsumo()!=null?m.getInsumo().getId():m.getProduto().getId();String o=m.getMovimentacaoOrigem()!=null?"Estorno #"+m.getMovimentacaoOrigem().getId():m.getItemCompra()!=null?"Compra #"+m.getItemCompra().getCompra().getId():m.getTipo().getDescricao();return MovimentacaoEstoqueResponse.builder().id(m.getId()).tipoItem(m.getTipoItem()).referenciaId(id).nomeHistorico(m.getNomeHistorico()).dataMovimentacao(m.getDataMovimentacao()).tipo(m.getTipo()).quantidade(m.getQuantidade()).unidadeHistorica(m.getUnidadeHistorica()).valorTotal(m.getValorTotal()).custoUnitario(m.getCustoUnitario()).origem(o).observacao(m.getObservacao()).build();}
 private void medio(SaldoEstoque s){if(s.getQuantidadeAtual().signum()==0){s.setCustoMedioAtual(zero6());s.setValorTotalEstoque(zero2());}else s.setCustoMedioAtual(s.getValorTotalEstoque().divide(s.getQuantidadeAtual(),6,RoundingMode.HALF_UP));}private BigDecimal qtd(BigDecimal q,UnidadeMedida u){if(q==null||q.signum()<=0)throw new BusinessException("Quantidade deve ser maior que zero.");if(q.stripTrailingZeros().scale()>3)throw new BusinessException("Quantidade deve ter no máximo três casas decimais.");if(u==UnidadeMedida.UNIDADE&&q.stripTrailingZeros().scale()>0)throw new BusinessException("Quantidade em unidade deve ser inteira.");return q.setScale(3,RoundingMode.UNNECESSARY);}private BigDecimal positivo(BigDecimal v){if(v==null||v.signum()<=0)throw new BusinessException("Valor deve ser maior que zero.");return dinheiro(v);}private BigDecimal dinheiro(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(2,RoundingMode.HALF_UP);}private BigDecimal zero2(){return BigDecimal.ZERO.setScale(2);}private BigDecimal zero6(){return BigDecimal.ZERO.setScale(6);}private String texto(String s){s=limpar(s);return s.isEmpty()?null:s;}private String limpar(String s){return s==null?"":s.trim();}private record Ref(TipoItemEstoque tipo,Long id,Insumo insumo,Produto produto,String nome,UnidadeMedida unidade,Boolean ativo,BigDecimal minimo){}
 private String formatarQuantidade(BigDecimal q,UnidadeMedida u){return q.setScale(u==UnidadeMedida.UNIDADE?0:3,RoundingMode.HALF_UP).toPlainString()+" "+u.getSimbolo();}
 private record Chave(TipoItemEstoque tipo,Long id){}private record Necessidade(Ref ref,BigDecimal quantidade){}
}
